inline double sunLongitudeUnwrapped(double jd) noexcept
{
    const double x = (jd - 2451545.0) / 36525.0;
    const double xs = x / 100.0;
    double v = 0.0;
    double p = 1.0;
    for (int i = 0; i < 6; ++i) { v += SunLongitudePolynomial[i] * p; p *= xs; }
    for (const EnvelopeTerm &e : SunLongitudeEnvelopes)
    {
        const double c = std::cos(e.omega * x);
        const double s = std::sin(e.omega * x);
        double q = 1.0;
        for (int m = 0; m <= e.degree; ++m)
        {
            v += (e.cosine[m] * c + e.sine[m] * s) * q;
            q *= xs;
        }
    }
    for (const Term &t : SunLongitudeExtras) v += t.amplitude * std::cos(t.omega * x + t.phase);
    return v - SunLongitudeOffset;
}

inline double sunLongitude(double jd) noexcept
{
    const double v = std::fmod(sunLongitudeUnwrapped(jd), 360.0);
    return v < 0.0 ? v + 360.0 : v;
}

inline double moonSunDifferenceUnwrapped(double jd) noexcept
{
    const double x = (jd - 2451545.0) / 36525.0;
    const double xs = x / 100.0;
    double v = MoonSunRate * x;
    double p = 1.0;
    for (int i = 0; i < 4; ++i) { v += MoonSunPolynomial[i] * p; p *= xs; }
    for (const EnvelopeTerm &e : MoonSunEnvelopes)
    {
        const double c = std::cos(e.omega * x);
        const double s = std::sin(e.omega * x);
        double q = 1.0;
        for (int m = 0; m <= e.degree; ++m)
        {
            v += (e.cosine[m] * c + e.sine[m] * s) * q;
            q *= xs;
        }
    }
    return v - MoonSunOffset;
}

inline double moonSunDifference(double jd) noexcept
{
    const double v = std::fmod(moonSunDifferenceUnwrapped(jd), 360.0);
    return v < 0.0 ? v + 360.0 : v;
}

inline double moonLongitude(double jd) noexcept
{
    const double v = std::fmod(sunLongitude(jd) + moonSunDifference(jd), 360.0);
    return v < 0.0 ? v + 360.0 : v;
}

// Correction relative to CumulativeDayMean * m (m is the continuous month
// count).  It includes the quadratic/cubic trend, so it is not the pointwise
// fit residual; see FIT_REPORT.md section 2.3.
inline double cumulativeDayResidual(std::int64_t monthAbsolute) noexcept
{
    const double m = static_cast<double>(monthAbsolute) - (monthAbsolute > 0 ? 1.0 : 0.0);
    const double x = m / 1000.0;
    double total = 0.0;
    double p = 1.0;
    for (double c : CumulativeDayPolynomial) { total += c * p; p *= x; }
    return total - CumulativeDayIntercept - CumulativeDayMean * m;
}

inline double synodicYearLength(std::int64_t yearAbsolute) noexcept
{
    const double x = (static_cast<double>(yearAbsolute) - 1.0) / 1000.0;
    double v = 0.0;
    double p = 1.0;
    for (double c : SynodicYearPolynomial) { v += c * p; p *= x; }
    return v;
}

inline double tropicalYearLength(std::int64_t yearAbsolute) noexcept
{
    const double x = (static_cast<double>(yearAbsolute) - 1.0) / 1000.0;
    double v = 0.0;
    double p = 1.0;
    for (double c : TropicalYearPolynomial) { v += c * p; p *= x; }
    return v;
}

// Leap months follow the astronomical no-mid-term rule, not a periodic bitmap.
// A time-only Waveform score cannot represent it; see FIT_REPORT.md.  The
// rule validated on this data uses sunLongitude() to count the 12 mid-terms
// (multiples of 30 degrees) in each lunar month and marks the first empty
// month of a 13-month synodic year as leap.
//
// Number of 30-degree boundaries crossed in [startJd, endJd); 0 means the
// lunar month has no 中气.  Use this with new-moon times from
// moonSunDifferenceUnwrapped() to implement isLeapMonth/isLeapYear.
inline int midTermCount(double startJd, double endJd) noexcept
{
    const double l0 = sunLongitudeUnwrapped(startJd);
    const double l1 = sunLongitudeUnwrapped(endJd);
    return static_cast<int>(std::floor(l1 / 30.0) - std::floor(l0 / 30.0));
}

